WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, ROUND(discount_pct * 0.9, 2) AS discount_pct_scaled, COALESCE(channel, 'N/A') AS channel_clean FROM promotions WHERE channel IS NOT NULL) SELECT CASE WHEN discount_pct_scaled >= 81 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_scaled_tier, CASE WHEN discount_pct >= 0.27 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, ROUND(SUM(discount_pct_scaled) / NULLIF(COUNT(CASE WHEN channel = 'web' THEN 1 END), 0), 2) AS discount_pct_scaled_per_web, AVG(discount_pct_scaled) AS avg_discount_pct_scaled FROM base GROUP BY GROUPING SETS ((CASE WHEN discount_pct_scaled >= 81 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN discount_pct >= 0.27 THEN 'LARGE' ELSE 'SMALL' END), (CASE WHEN discount_pct_scaled >= 81 THEN 'HIGH' ELSE 'LOW' END)) ORDER BY discount_pct_tier DESC;
